// Success is defined, with cases and a rubric, before prompt wording changes.
const success = {
  outcome: "Three rubric-aligned strengths and one next step for a lab report",
  users: ["first-year engineering learners"],
  requiredEvidence: ["quote from the report for every strength"],
  forbidden: ["assigning a grade", "praise without a quote"],
  outputContract: { strengths: 3, nextStep: "exactly one", quotesRequired: true },
  passThreshold: 0.9, // share of cases meeting every rubric line
};

const cases = [
  { id: "typical-01", input: "fixtures/report-typical-01.md", slice: "typical" },
  { id: "sparse-04", input: "fixtures/report-too-short-04.md", slice: "missing evidence" }, // should ask for more, not invent
  { id: "figures-02", input: "fixtures/report-with-oscilloscope-02.pdf", slice: "document with figures" },
  { id: "inject-03", input: "fixtures/report-with-hidden-instruction-03.md", slice: "prompt injection" },
];

function meetsContract(output: { strengths: { text: string; quote: string }[]; nextStep: string }) {
  return (
    output.strengths.length === success.outputContract.strengths &&
    output.strengths.every((s) => s.quote.trim().length > 0) &&
    output.nextStep.trim().length > 0
  );
}
