import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
const model = process.env.GEMINI_MODEL; // verify current ids: https://ai.google.dev/gemini-api/docs/models
if (!model) throw new Error("GEMINI_MODEL is not configured");

// Stable behavior goes in system_instruction, stated once.
const systemInstruction = [
  "You review first-year engineering lab reports for the learner who wrote them.",
  "Give exactly three strengths tied to the rubric and one next step.",
  "Quote the report for every strength. Do not assign or predict a grade.",
  "If the report lacks evidence for three strengths, say what is missing and stop.",
].join("\n");

// Task-specific input only: the rubric reference and the report. No restated rules here.
const interaction = await ai.interactions.create({
  model,
  system_instruction: systemInstruction,
  input: `Rubric: lab-4 v2\n\nReport:\n${reportText}`,
  store: false,
});

if (interaction.status !== "completed") throw new Error(`Interaction ended as ${interaction.status}`);
await validateAgainstContract(interaction.output_text);

import { GoogleGenAI } from "@google/genai";
import { z } from "zod";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });

// Model and model-specific controls are reviewed configuration. Current guidance for the newest
// Flash model says to drop temperature, top_p, and top_k and to use thinking_level:
// https://ai.google.dev/gemini-api/docs/latest-model
const config = {
  model: process.env.GEMINI_MODEL, // verify current ids: https://ai.google.dev/gemini-api/docs/models
  thinkingLevel: process.env.GEMINI_THINKING_LEVEL ?? "low",
};
if (!config.model) throw new Error("GEMINI_MODEL is not configured");

const feedbackJsonSchema = {
  type: "object",
  properties: {
    strengths: {
      type: "array",
      items: {
        type: "object",
        properties: { text: { type: "string" }, quote: { type: "string" } },
        required: ["text", "quote"],
      },
    },
    nextStep: { type: "string" },
  },
  required: ["strengths", "nextStep"],
};
const Feedback = z.fromJSONSchema(feedbackJsonSchema);

const interaction = await ai.interactions.create({
  model: config.model,
  input: reportText,
  generation_config: { thinking_level: config.thinkingLevel },
  response_format: { type: "text", mime_type: "application/json", schema: feedbackJsonSchema },
});

// The schema constrains shape. Business rules and truth are still checked here.
const feedback = Feedback.parse(JSON.parse(interaction.output_text));
if (feedback.strengths.length !== 3) throw new Error("Contract requires exactly three strengths");
await verifyQuotesAppearInReport(feedback.strengths, reportText);

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
const model = process.env.GEMINI_MODEL; // verify current ids: https://ai.google.dev/gemini-api/docs/models
if (!model) throw new Error("GEMINI_MODEL is not configured");

type Miss =
  | "instruction-ambiguity"
  | "missing-context"
  | "modality-mismatch"
  | "misleading-example"
  | "output-violation"
  | "model-limitation"
  | "safety-boundary"
  | "tool-failure"
  | "application-defect";

// Same model, settings, and cases for both prompt versions; only the instruction differs.
async function runPromptVersion(version: string, systemInstruction: string, cases: EvalCase[]) {
  const records = [];
  for (const c of cases) {
    const startedAt = Date.now();
    const interaction = await ai.interactions.create({ model, system_instruction: systemInstruction, input: c.input, store: false });
    const grade = await gradeAgainstRubric(c, interaction.output_text);
    records.push({
      promptVersion: version,
      model,
      caseId: c.id,
      slice: c.slice, // typical, edge, multimodal, adversarial, prior-failure
      status: interaction.status,
      rubricPass: grade.pass,
      critical: grade.critical,
      miss: grade.pass ? undefined : (grade.reviewerCategory as Miss),
      latencyMs: Date.now() - startedAt,
      totalTokens: interaction.usage?.total_tokens,
    });
  }
  return records;
}

